const game = new GF.Game({id:'core-awakening',title:'Core Awakening',width:960,height:540,palette:['#0A4D68','#3E7C9D','#FFC93C','#FF6A13'],background:'#0A4D68'});

let player = {x:480,y:270,health:3};
let enemies = []; 
let salvage = []; 
let enemyAttackPatterns = [0.5, 1, 1.5];

function spawnEnemy() {
    enemies.push({x:GF.math.rand(100,860),y:GF.math.rand(100,440),health:1});
}

function salvageComponent() {
    salvage.push({x:player.x,y:player.y});
    game.addScore(1);
    game.burst(player.x, player.y, {count:10,speed:100,size:3,life:0.5,colors:['#FFC93C']});
    GF.Sfx.beep({freq:600,dur:0.1});
}

game.add('play', {
    init() {
        for(let i=0; i<3; i++) spawnEnemy();
        document.getElementById('healthValue').innerText = player.health;
        document.getElementById('scoreValue').innerText = game.score;
    },
    update(dt) {
        if(game.input.pressed('Space')) salvageComponent();
        enemies.forEach((enemy, index) => {
            if(enemy.health <= 0) {
                game.shake(6, 0.3);
                game.burst(enemy.x, enemy.y, {count:15,speed:80,size:4,life:0.6,colors:['#FF6A13']});
                game.addScore(1);
                GF.Sfx.noise({dur:0.2,vol:0.3});
                enemies.splice(index, 1);
            }
        });
        if(player.health <= 0) game.gameOver({message:'Game Over'});
        document.getElementById('healthValue').innerText = player.health;
        document.getElementById('scoreValue').innerText = game.score;
    },
    draw(ctx) {
        ctx.fillStyle = '#0A4D68';
        ctx.fillRect(0, 0, 960, 540);
        enemies.forEach(enemy => {
            ctx.fillStyle = '#3E7C9D';
            ctx.strokeStyle = '#FFC93C';
            ctx.lineWidth = 2;
            ctx.strokeRect(enemy.x, enemy.y, 40, 40);
            ctx.fillRect(enemy.x, enemy.y, 40, 40);
        });
        salvage.forEach(comp => {
            ctx.fillStyle = '#FFC93C';
            ctx.fillRect(comp.x, comp.y, 20, 20);
        });
        GF.Draw.text(ctx, 'Health: ' + player.health, 20, 30, {size:20,color:'#FFC93C'});
        GF.Draw.text(ctx, 'Score: ' + game.score, 20, 60, {size:20,color:'#FFC93C'});
    }
});

game.titleScreen({
    subtitle:'Press any key to start',
    onStart() { game.go('play'); }
});
